/**
 * @method
 * @name p2b#fetchTicker
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
 * @see https://github.com/P2B-team/p2b-api-docs/blob/master/api-doc.md#ticker
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *P2b) FetchTickerAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *P2b) fetchTickerBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	if IsTrue(IsEqual(this.Markets, nil)) {

		retRes49212 := (<-this.LoadMarketsAsync())
		PanicOnError(retRes49212)
	}
	var market any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": GetValue(market, "id"),
	}

	response := (<-this.PublicGetTicker(this.Extend(request, params)))
	PanicOnError(response)
	//
	//    {
	//        success: true,
	//        errorCode: '',
	//        message: '',
	//        result: {
	//            bid: '0.342',
	//            ask: '0.3421',
	//            open: '0.3317',
	//            high: '0.3499',
	//            low: '0.3311',
	//            last: '0.3421',
	//            volume: '17855383.1',
	//            deal: '6107478.3423',
	//            change: '3.13'
	//        },
	//        cache_time: '1699252953.832795',
	//        current_time: '1699252958.859391'
	//    }
	//
	var result any = this.SafeValue(response, "result", map[string]any{})
	var timestamp any = this.SafeIntegerProduct(response, "cache_time", 1000)

	ch <- this.Extend(map[string]any{
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}, this.ParseTicker(result, market))
	return nil
}
func (this *P2b) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	// parseTickers
	//
	//    {
	//        at: '1699252631',
	//        ticker: {
	//            bid: '0.0000332',
	//            ask: '0.0000333',
	//            low: '0.0000301',
	//            high: '0.0000338',
	//            last: '0.0000333',
	//            vol: '15.66',
	//            deal: '0.000501828',
	//            change: '10.63'
	//        }
	//    }
	//
	// parseTicker
	//
	//    {
	//        bid: '0.342',
	//        ask: '0.3421',
	//        open: '0.3317',
	//        high: '0.3499',
	//        low: '0.3311',
	//        last: '0.3421',
	//        volume: '17855383.1',
	//        deal: '6107478.3423',
	//        change: '3.13'
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.SafeIntegerProduct(ticker, "at", 1000)
	if IsTrue(InOp(ticker, "ticker")) {
		ticker = this.SafeValue(ticker, "ticker")
	}
	var last any = this.SafeString(ticker, "last")
	return this.SafeTicker(map[string]any{
		"symbol":        this.SafeString(market, "symbol"),
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open"),
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    this.SafeString(ticker, "change"),
		"average":       nil,
		"baseVolume":    this.SafeString2(ticker, "vol", "volume"),
		"quoteVolume":   this.SafeString(ticker, "deal"),
		"info":          ticker,
	}, market)
}

