func (this *P2b) ParseOrder(order any, optionalArgs ...any) any {
	//
	// cancelOrder, fetchOpenOrders, createOrder
	//
	//    {
	//        "orderId": 171906478744,
	//        "market": "ETH_BTC",
	//        "price": "0.04348",
	//        "side": "buy",
	//        "type": "limit",
	//        "timestamp": 1698484861.746517,
	//        "dealMoney": "0",
	//        "dealStock": "0",
	//        "amount": "0.0277",
	//        "takerFee": "0.002",
	//        "makerFee": "0.002",
	//        "left": "0.0277",
	//        "dealFee": "0"
	//    }
	//
	// fetchClosedOrders
	//
	//    {
	//        "id": 171366547790,           // Order id
	//        "amount": "0.00032",          // Original amount
	//        "price": "34293.92",          // Order price
	//        "type": "limit",              // Order type
	//        "side": "sell",               // Order side
	//        "ctime": 1698237533.497241,   // Order creation time
	//        "ftime": 1698237535.41196,    // Order fill time
	//        "market": "BTC_USDT",         // Market name
	//        "takerFee": "0.0018",         // Taker fee
	//        "makerFee": "0.0016",         // Market fee
	//        "dealFee": "0.01755848704",   // Deal fee
	//        "dealStock": "0.00032",       // Filled amount
	//        "dealMoney": "10.9740544"     // Filled total
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.SafeIntegerProduct2(order, "timestamp", "ctime", 1000)
	var marketId any = this.SafeString(order, "market")
	market = this.SafeMarket(marketId, market)
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 this.SafeString2(order, "id", "orderId"),
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             GetValue(market, "symbol"),
		"type":               this.SafeString(order, "type"),
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               this.SafeString(order, "side"),
		"price":              this.SafeString(order, "price"),
		"triggerPrice":       nil,
		"amount":             this.SafeString(order, "amount"),
		"cost":               nil,
		"average":            nil,
		"filled":             this.SafeString(order, "dealStock"),
		"remaining":          this.SafeString(order, "left"),
		"status":             nil,
		"fee": map[string]any{
			"currency": GetValue(market, "quote"),
			"cost":     this.SafeString(order, "dealFee"),
		},
		"trades": nil,
	}, market)
}
func (this *P2b) Sign(path any, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	method := GetArg(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var url any = Add(Add(GetValue(GetValue(this.Urls, "api"), api), "/"), this.ImplodeParams(path, params))
	params = this.Omit(params, this.ExtractParams(path))
	if IsTrue(IsEqual(method, "GET")) {
		if IsTrue(IsGreaterThan(GetArrayLength(ObjectKeys(params)), 0)) {
			url = Add(url, Add("?", this.Urlencode(params)))
		}
	}
	if IsTrue(IsEqual(api, "private")) {
		AddElementToObject(params, "request", Add("/api/v2/", path))
		AddElementToObject(params, "nonce", ToString(this.Nonce()))
		var payload string = this.StringToBase64(this.Json(params)) // Body json encoded in base64
		headers = map[string]any{
			"Content-Type":    "application/json",
			"X-TXC-APIKEY":    this.ApiKey,
			"X-TXC-PAYLOAD":   payload,
			"X-TXC-SIGNATURE": this.Hmac(this.Encode(payload), this.Encode(this.Secret), sha512),
		}
		body = this.Json(params)
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
func (this *P2b) HandleErrors(code any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsTrue(IsEqual(response, nil)) {
		return nil
	}
	//
	//     {"success":false,"errorCode":2021,"message":"Unknown market.","result":[]}
	//     {"success":false,"errorCode":1010,"message":"This action is unauthorized.","result":[]}
	//     {"success":true,"errorCode":"","message":"","result":{...},"cache_time":1787611797.535462,"current_time":1787611797.535973}
	//
	var success any = this.SafeBool(response, "success", true)
	if IsTrue(!IsEqual(success, true)) {
		var errorCode any = this.SafeString(response, "errorCode")
		var feedback any = Add(Add(this.Id, " "), body)
		this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), errorCode, feedback)
		if IsTrue(IsLessThan(code, 400)) {
			panic(ExchangeError(feedback))
		}
	}
	return nil
}

func NewP2b(userConfig map[string]any) *P2b {
	p := newP2b()
	p.Init(userConfig)
	return p
}

func (this *P2b) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

